import re
from collections import defaultdict

# -------------------------------------------------------------
# Helper functions supplied by the environment
# -------------------------------------------------------------
# node_by_title(doc, title) -> node
# node_by_id(doc, node_id) -> node
# children(doc, node) -> list of child nodes
# scope_nodes(doc, scope) -> list of child nodes of the scope
# table_rows(node) -> generator of (row_index, {column: cell}) for each row in a table node
# -------------------------------------------------------------


# -------------------------------------------------------------
# Private helpers
# -------------------------------------------------------------
def _node_for_suffix(doc, scope_node, suffix):
    """Return the first child of scope_node whose title ends with suffix."""
    for n in children(doc, scope_node):
        if n["title"].endswith(suffix):
            return n
    return None


def _parse_numeric(s):
    """Parse a string as int or float; return None if not numeric."""
    if s is None:
        return None
    s = s.strip()
    if s == "":
        return None
    try:
        if re.fullmatch(r"-?\d+", s):
            return int(s)
        if re.fullmatch(r"-?\d+(\.\d+)?", s):
            return float(s)
    except Exception:
        pass
    return None


# -------------------------------------------------------------
# PUBLIC API
# -------------------------------------------------------------
def entities(doc, scope):
    """Return all distinct entities referenced in the scope."""
    scope_node = node_by_title(doc, f"^{re.escape(scope)}$")
    if scope_node is None:
        return []

    prod_node = _node_for_suffix(doc, scope_node, "Products")
    if prod_node is None:
        return []

    ents = []
    for row_index, row in table_rows(prod_node):
        pid = row["product"]
        desc = f"{pid} ({row['group']}-{row['sub-group']}, {row['storage location']})"
        ents.append({"id": pid, "description": desc})
    return ents


def recorded_end(doc, scope):
    """Last day covered by the scope's Daily ledger."""
    scope_node = node_by_title(doc, f"^{re.escape(scope)}$")
    if scope_node is None:
        return None

    ledger_node = _node_for_suffix(doc, scope_node, "Daily ledger")
    if ledger_node is None:
        return None

    max_day = None
    for row_index, row in table_rows(ledger_node):
        d = _parse_numeric(row.get("day"))
        if d is not None:
            if max_day is None or d > max_day:
                max_day = d
    return max_day


def inputs(doc, scope):
    """Return all input records for the process."""
    scope_node = node_by_title(doc, f"^{re.escape(scope)}$")
    if scope_node is None:
        return []

    res = []

    # 1. Opening stock (initial state of each product)
    prod_node = _node_for_suffix(doc, scope_node, "Products")
    if prod_node:
        for row_index, row in table_rows(prod_node):
            pid = row["product"]
            stock = _parse_numeric(row.get("opening stock"))
            if stock is None:
                continue
            res.append({
                "id": f"opening_stock:{pid}",
                "time": None,
                "kind": "initial stock",
                "entities": [pid],
                "fields": {"opening_stock": stock},
                "src": [[prod_node["node_id"], row_index, ["product", "opening stock"]]],
            })

    # 2. Daily production and orders (entries that drive the process)
    ledger_node = _node_for_suffix(doc, scope_node, "Daily ledger")
    if ledger_node:
        for row_index, row in table_rows(ledger_node):
            pid = row["product"]
            day = _parse_numeric(row.get("day"))
            if day is None:
                continue
            produced = _parse_numeric(row.get("produced"))
            ordered = _parse_numeric(row.get("ordered"))

            if produced is not None and produced > 0:
                res.append({
                    "id": f"produced:{pid}:{int(day)}",
                    "time": day,
                    "kind": "production arrival",
                    "entities": [pid],
                    "fields": {"produced_units": produced},
                    "src": [[ledger_node["node_id"], row_index, ["product", "produced"]]],
                })
            if ordered is not None and ordered > 0:
                res.append({
                    "id": f"order:{pid}:{int(day)}",
                    "time": day,
                    "kind": "sales order created",
                    "entities": [pid],
                    "fields": {"ordered_units": ordered},
                    "src": [[ledger_node["node_id"], row_index, ["product", "ordered"]]],
                })

    # 3. Dispatch capacity (constant for a plant)
    # The capacity is mentioned in the scope's own text node
    if scope_node["kind"] == "text":
        cap_match = re.search(r'daily dispatch capacity:\s*([0-9,]+)\s*kg', scope_node["text"], re.I)
        if cap_match:
            cap = float(cap_match.group(1).replace(",", ""))
            res.append({
                "id": f"dispatch_capacity:{scope}",
                "time": None,
                "kind": "dispatch capacity",
                "entities": [],
                "fields": {"dispatch_capacity_kg": cap},
                "src": [[scope_node["node_id"]]],
            })

    # 4. Order book – open orders carried over from previous period
    book_node = _node_for_suffix(doc, scope_node, "Order book")
    if book_node:
        # For Plant 1912 style book (product, day placed, units still open)
        for row_index, row in table_rows(book_node):
            pid = row.get("product")
            if pid is None:
                continue
            units = _parse_numeric(row.get("units still open"))
            if units is None:
                continue
            day_placed = _parse_numeric(row.get("day placed"))
            res.append({
                "id": f"book_open:{pid}:{int(day_placed)}",
                "time": day_placed,
                "kind": "book open order",
                "entities": [pid],
                "fields": {"open_units": units},
                "src": [[book_node["node_id"], row_index, ["product", "units still open"]]],
            })

    return res


def outcomes(doc, scope):
    """Return all outcome records produced by the process."""
    scope_node = node_by_title(doc, f"^{re.escape(scope)}$")
    if scope_node is None:
        return []

    res = []

    # 1. Ledger results – shipped, backordered, stock
    ledger_node = _node_for_suffix(doc, scope_node, "Daily ledger")
    if ledger_node:
        for row_index, row in table_rows(ledger_node):
            day = _parse_numeric(row.get("day"))
            if day is None:
                continue
            pid = row["product"]

            shipped = _parse_numeric(row.get("shipped"))
            if shipped is not None:
                res.append({
                    "time": day,
                    "kind": "shipped",
                    "entities": [pid],
                    "value": shipped,
                    "src": [[ledger_node["node_id"], row_index, ["product", "shipped"]]],
                })
            backo = _parse_numeric(row.get("backordered"))
            if backo is not None:
                res.append({
                    "time": day,
                    "kind": "backordered",
                    "entities": [pid],
                    "value": backo,
                    "src": [[ledger_node["node_id"], row_index, ["product", "backordered"]]],
                })
            stock = _parse_numeric(row.get("stock"))
            if stock is not None:
                res.append({
                    "time": day,
                    "kind": "stock",
                    "entities": [pid],
                    "value": stock,
                    "src": [[ledger_node["node_id"], row_index, ["product", "stock"]]],
                })

    # 2. Events lists – capacity reached, stock exhaust, etc.
    events_node = _node_for_suffix(doc, scope_node, "Events")
    if events_node:
        known_products = set(ent["id"] for ent in entities(doc, scope))

        for line_index, line in enumerate(events_node["lines"]):
            day_match = re.search(r'Day\s+(\d+)', line)
            if not day_match:
                continue
            day = float(day_match.group(1))

            # Capacity reached
            if "dispatch capacity reached" in line:
                cap_used_match = re.search(r'\(([\d\.]+)\s+of\s+[\d\.]+\s+kg dispatched\)', line)
                cap_used = float(cap_used_match.group(1)) if cap_used_match else None
                res.append({
                    "time": day,
                    "kind": "capacity_reached",
                    "entities": [],
                    "value": cap_used,
                    "src": [[events_node["node_id"], line_index]],
                })
                continue

            # Runs out of stock
            if "runs out of stock" in line:
                prod_match = re.search(r'(\w+)\s+runs out of stock', line)
                pid = prod_match.group(1) if prod_match else None
                units_match = re.search(r'\((\d+)\s+units backordered\)', line)
                units = float(units_match.group(1)) if units_match else None
                if pid in known_products:
                    res.append({
                        "time": day,
                        "kind": "stock_exhaust",
                        "entities": [pid],
                        "value": units,
                        "src": [[events_node["node_id"], line_index]],
                    })
                continue

            # Order fully backordered
            if "fully backordered" in line:
                prod_match = re.search(r'order for\s+(\w+)\s+placed', line)
                pid = prod_match.group(1) if prod_match else None
                if pid and pid in known_products:
                    res.append({
                        "time": day,
                        "kind": "order_fully_backordered",
                        "entities": [pid],
                        "value": None,
                        "src": [[events_node["node_id"], line_index]],
                    })
                continue

            # Backlog cleared
            if "backlog cleared" in line:
                prod_match = re.search(r'backlog cleared\.\s*([A-Z0-9]+)', line)
                pid = prod_match.group(1) if prod_match else None
                if pid and pid in known_products:
                    res.append({
                        "time": day,
                        "kind": "backlog_cleared",
                        "entities": [pid],
                        "value": None,
                        "src": [[events_node["node_id"], line_index]],
                    })
                continue

    return res


def params(doc, scope):
    """Return constant parameters defined for the plant."""
    scope_node = node_by_title(doc, f"^{re.escape(scope)}$")
    if scope_node is None or scope_node["kind"] != "text":
        return {}

    # Dispatch capacity is already captured as an input, but we expose it as a param
    cap_match = re.search(r'daily dispatch capacity:\s*([0-9,]+)\s*kg', scope_node["text"], re.I)
    if not cap_match:
        return {}

    cap = float(cap_match.group(1).replace(",", ""))
    return {"dispatch_capacity_kg": cap}
